        conn.close();
    };
    signal?.addEventListener("abort", closeConnection, { once: true });
    try {
        signal?.throwIfAborted();
        await writeAll(
            conn,
            new TextEncoder().encode(
                `GET ${path} HTTP/1.1\r\nHost: ${base.host}\r\n${
                    Object.entries(endpoint.headers).map(([name, value]) =>
                        `${name}: ${value}\r\n`
                    ).join("")
                }Connection: Upgrade\r\nUpgrade: tcp\r\n\r\n`,
            ),
        );
        const { status, headers, rest } = await readHead(conn);
        if (status !== 101) {
            const length = Number(headers.get("content-length") ?? 0);
            const body = await readExactly(conn, rest, length);
            throw new HttpError(status, new TextDecoder().decode(body));
        }
        return duplex(conn, rest);
    } catch (error) {
        closeConnection();
        throw signal?.aborted ? signal.reason : error;
    } finally {
        signal?.removeEventListener("abort", closeConnection);
    }
}

export function connectPreview(
    url: string | URL,
    signal?: AbortSignal,
): Promise<Tunnel> {
    return openUpgrade({ url: new URL(url), headers: {} }, "/", signal);
}

export function duplex(
    conn: Deno.Conn,
    already_read = new Uint8Array(),
): Tunnel {
    let open_directions = 2;
    let closed = false;
    const close = () => {
        if (closed) return;
        closed = true;
        conn.close();
    };
    const finish = () => {
        if (--open_directions === 0) close();
    };
    const readable = new ReadableStream<Uint8Array<ArrayBuffer>>({
        start(controller) {
            if (already_read.byteLength > 0) controller.enqueue(already_read);
        },
        async pull(controller) {
            const buffer = new Uint8Array(READ_CHUNK_BYTES);
            const count = await conn.read(buffer);
            if (count === null) {
                controller.close();
                finish();
            } else {
                controller.enqueue(buffer.subarray(0, count));
            }
        },
        cancel: finish,
    });
    const writable = new WritableStream<Uint8Array<ArrayBuffer>>({
        write: (chunk) => writeAll(conn, chunk),
        async close() {
            await conn.closeWrite();
            finish();
        },
        abort: close,
    });
    return { readable, writable, close };
}

function connect(base: URL): Promise<Deno.Conn> {
    const hostname = base.hostname.replace(/^\[(.*)\]$/, "$1");
    if (base.protocol === "https:") {
        return Deno.connectTls({ hostname, port: Number(base.port || 443) });
    }
    if (base.protocol === "http:") {
        return Deno.connect({ hostname, port: Number(base.port || 80) });
    }
    throw new TypeError(`unsupported machine URL protocol ${base.protocol}`);
}

async function writeAll(
    conn: Deno.Conn,
    bytes: Uint8Array<ArrayBuffer>,
): Promise<void> {
    let written = 0;
    while (written < bytes.byteLength) {
        written += await conn.write(bytes.subarray(written));
    }
}

async function readHead(conn: Deno.Conn): Promise<{
    status: number;
    headers: Headers;
    rest: Uint8Array<ArrayBuffer>;
}> {
    let received = new Uint8Array();
    while (true) {
        const end = indexOf(received, HEAD_END);
        if (end >= 0) {
            const [status_line = "", ...lines] = new TextDecoder()
                .decode(received.subarray(0, end))
                .split("\r\n");
            const status = Number(status_line.split(" ")[1]);
            if (!status_line.startsWith("HTTP/1.1 ") || !status) {
                throw new Error(`malformed tunnel response: ${status_line}`);
            }
            const headers = new Headers();
            for (const line of lines) {
                const colon = line.indexOf(":");
                if (colon > 0) {
                    headers.append(
                        line.slice(0, colon),
                        line.slice(colon + 1).trim(),
                    );
                }
            }
            return {
                status,
                headers,
                rest: received.slice(end + HEAD_END.length),
            };
        }
        if (received.byteLength > MAX_HEAD_BYTES) {
            throw new Error("tunnel response head is too large");
        }
        received = concat(received, await readSome(conn));
    }
}

async function readExactly(
    conn: Deno.Conn,
    already_read: Uint8Array<ArrayBuffer>,
    length: number,
): Promise<Uint8Array<ArrayBuffer>> {
    let received = already_read;
    while (received.byteLength < Math.min(length, MAX_HEAD_BYTES)) {
        received = concat(received, await readSome(conn));
    }
    return received.subarray(0, length);
}

async function readSome(conn: Deno.Conn): Promise<Uint8Array<ArrayBuffer>> {
    const buffer = new Uint8Array(READ_CHUNK_BYTES);
    const count = await conn.read(buffer);
    if (count === null) {
        throw new Error("connection closed during tunnel setup");
    }
    return buffer.subarray(0, count);
}

function concat(
    a: Uint8Array<ArrayBuffer>,
    b: Uint8Array<ArrayBuffer>,
): Uint8Array<ArrayBuffer> {
    const joined = new Uint8Array(a.byteLength + b.byteLength);
    joined.set(a);
    joined.set(b, a.byteLength);
    return joined;
}

function indexOf(
    haystack: Uint8Array<ArrayBuffer>,
    needle: Uint8Array<ArrayBuffer>,
): number {
    outer: for (let i = 0; i + needle.byteLength <= haystack.byteLength; i++) {
        for (let j = 0; j < needle.byteLength; j++) {
            if (haystack[i + j] !== needle[j]) continue outer;
        }
        return i;
    }
    return -1;
}
import assert from "node:assert/strict";
import { Machine } from "../src/machine.ts";
import type { Forward } from "../src/forward.ts";

async function bounded<T>(promise: Promise<T>, ms = 1000): Promise<T> {
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
        return await Promise.race([
            promise,
            new Promise<never>((_, reject) => {
                timer = setTimeout(
                    () => reject(new Error("forward.close() did not settle")),
                    ms,
                );
            }),
        ]);
    } finally {
        clearTimeout(timer);
    }
}

async function pending(
    count: number,
    run: (
        forward: Forward,
        clients: Deno.TcpConn[],
        remotes: Deno.TcpConn[],
    ) => Promise<void>,
): Promise<void> {
    const listener = Deno.listen({ hostname: "127.0.0.1", port: 0 });
    const machine = new Machine(`http://127.0.0.1:${listener.addr.port}/`);
    const forward = machine.forward(3000);
    const clients: Deno.TcpConn[] = [];
    const remotes: Deno.TcpConn[] = [];
    try {
        for (let i = 0; i < count; i++) {
            clients.push(
                await Deno.connect({
                    hostname: "127.0.0.1",
                    port: forward.port,
                }),
            );
            const remote = await bounded(listener.accept());
            remotes.push(remote);
            let header = "";
            const bytes = new Uint8Array(4096);
            while (!header.includes("\r\n\r\n")) {
                const n = await bounded(remote.read(bytes));
                assert.notEqual(n, null);
                header += new TextDecoder().decode(bytes.subarray(0, n!));
            }
            assert.match(header, /Upgrade: tcp/i);
        }
        await run(forward, clients, remotes);
    } finally {
        for (const conn of [...clients, ...remotes]) {
            try {
                conn.close();
            } catch {}
        }
        listener.close();
        await bounded(forward.close().catch(() => {}));
    }
}

Deno.test("closing a forward cancels an unanswered upgrade", () =>
    pending(1, async (forward, _clients, remotes) => {
        const closing = forward.close();
        closing.catch(() => {});
        await bounded(closing);
        assert.equal(await bounded(remotes[0]!.read(new Uint8Array(1))), null);
    }));

Deno.test("closing a forward cancels every pending upgrade", () =>
    pending(3, async (forward, _clients, remotes) => {
        const closing = forward.close();
        closing.catch(() => {});
        await bounded(closing);
        for (const remote of remotes) {
            assert.equal(await bounded(remote.read(new Uint8Array(1))), null);
        }
    }));

Deno.test("a client disconnect during setup still allows the forward to close", () =>
    pending(1, async (forward, clients, remotes) => {
        clients[0]!.close();
        const closing = forward.close();
        closing.catch(() => {});
        await bounded(closing);
        assert.equal(await bounded(remotes[0]!.read(new Uint8Array(1))), null);
    }));

Deno.test("an established forward still carries bytes in both directions", () =>
    pending(1, async (forward, clients, remotes) => {
        const client = clients[0]!;
        const remote = remotes[0]!;
        await remote.write(
            new TextEncoder().encode(
                "HTTP/1.1 101 Switching Protocols\r\nConnection: Upgrade\r\nUpgrade: tcp\r\n\r\n",
            ),
        );
        await client.write(new TextEncoder().encode("ping"));
        const data = new Uint8Array(4);
        assert.equal(await bounded(remote.read(data)), 4);
        assert.equal(new TextDecoder().decode(data), "ping");
        await remote.write(new TextEncoder().encode("pong"));
        assert.equal(await bounded(client.read(data)), 4);
        assert.equal(new TextDecoder().decode(data), "pong");
        await bounded(forward.close());
    }));

